import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import {
  cogProtocol,
  locationValues,
  setColorFunction,
} from '@geomatico/maplibre-cog-protocol';
import './style.css';

// Local EPSG:3857 Cloud Optimized GeoTIFF generated by pipeline/04_export_cog.py
const COG_URL = `${window.location.origin}/cogs/sf_100yr_slr0ft.tif`;

// Register the COG protocol handler with MapLibre GL
maplibregl.addProtocol('cog', cogProtocol);

// Custom flood depth color ramp (meters): transparent <= 0.05m, shallow cyan -> deep indigo
const DEPTH_STOPS = [
  { depth: 0.05, color: [186, 230, 253, 140] },
  { depth: 0.3, color: [56, 189, 248, 185] },
  { depth: 1.0, color: [37, 99, 235, 210] },
  { depth: 2.0, color: [30, 58, 138, 230] },
  { depth: 3.5, color: [88, 28, 135, 245] },
];

function floodDepthColorRamp(pixel, color, metadata) {
  const depth = pixel[0];
  if (
    depth === undefined ||
    Number.isNaN(depth) ||
    (metadata.noData !== undefined && depth === metadata.noData) ||
    depth <= 0.05
  ) {
    color.set([0, 0, 0, 0]);
    return;
  }

  if (depth >= DEPTH_STOPS[DEPTH_STOPS.length - 1].depth) {
    color.set(DEPTH_STOPS[DEPTH_STOPS.length - 1].color);
    return;
  }

  for (let i = 0; i < DEPTH_STOPS.length - 1; i++) {
    const a = DEPTH_STOPS[i];
    const b = DEPTH_STOPS[i + 1];
    if (depth >= a.depth && depth <= b.depth) {
      const t = (depth - a.depth) / (b.depth - a.depth);
      color[0] = Math.round(a.color[0] + t * (b.color[0] - a.color[0]));
      color[1] = Math.round(a.color[1] + t * (b.color[1] - a.color[1]));
      color[2] = Math.round(a.color[2] + t * (b.color[2] - a.color[2]));
      color[3] = Math.round(a.color[3] + t * (b.color[3] - a.color[3]));
      return;
    }
  }
}

setColorFunction(COG_URL, floodDepthColorRamp);

const map = new maplibregl.Map({
  container: 'map',
  style: {
    version: 8,
    sources: {
      osm: {
        type: 'raster',
        tiles: ['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],
        tileSize: 256,
        attribution: '&copy; OpenStreetMap contributors',
      },
    },
    layers: [
      {
        id: 'osm-basemap',
        type: 'raster',
        source: 'osm',
      },
    ],
  },
  center: [-122.4194, 37.7749], // San Francisco
  zoom: 12,
});

map.addControl(new maplibregl.NavigationControl(), 'top-right');

map.on('load', () => {
  map.addSource('flood-cog', {
    type: 'raster',
    url: `cog://${COG_URL}`,
    tileSize: 256,
  });

  map.addLayer({
    id: 'flood-depth-layer',
    type: 'raster',
    source: 'flood-cog',
  });
});

// Click-to-query pixel flood depth from the COG
const popup = new maplibregl.Popup({ closeButton: true, closeOnClick: true });

map.on('click', async (e) => {
  const { lng, lat } = e.lngLat;
  try {
    const values = await locationValues(
      COG_URL,
      { latitude: lat, longitude: lng },
      Math.round(map.getZoom())
    );
    const depth = values?.[0];
    const text =
      depth === undefined || Number.isNaN(depth) || depth <= 0.05
        ? 'Dry / No flood data'
        : `Flood depth: <strong>${depth.toFixed(2)} m</strong> (${(depth * 3.28084).toFixed(2)} ft)`;

    popup.setLngLat(e.lngLat).setHTML(text).addTo(map);
  } catch {
    popup
      .setLngLat(e.lngLat)
      .setHTML('Unable to query COG (ensure local COG exists in <code>web/public/cogs/</code>).')
      .addTo(map);
  }
});
